script:
# Server Script: enc_amend
# type: API
# doctype: -
# event: Before Insert
# api_method: enc_amend
# allow_guest: 0
# frequency: All
# disabled: 0

user = frappe.session.user
admin = False
ok = False
for r in ["Physician", "Healthcare Administrator", "System Manager"]:
    if frappe.db.exists("Has Role", {"parent": user, "role": r}):
        ok = True
for r in ["Healthcare Administrator", "System Manager"]:
    if frappe.db.exists("Has Role", {"parent": user, "role": r}):
        admin = True
if not ok:
    frappe.throw("Only doctors can edit a consultation.")

f = frappe.form_dict
name = (f.get("encounter") or "").strip()
if not name:
    appt = (f.get("appointment") or "").strip()
    if appt:
        enc = frappe.get_all("Patient Encounter", filters={"appointment": appt, "docstatus": 1},
            fields=["name"], order_by="modified desc", limit=1)
        if enc:
            name = enc[0].name
if not name or not frappe.db.exists("Patient Encounter", name):
    frappe.throw("That consultation was not found.")
old = frappe.get_doc("Patient Encounter", name)
if old.docstatus != 1:
    frappe.throw("Only a completed consultation can be edited this way.")
if not old.appointment:
    frappe.throw("This consultation has no appointment, so it cannot be reopened from this page. Amend it in Desk.")
if not admin:
    mine = frappe.db.get_value("Healthcare Practitioner", {"user_id": user}, "name")
    if mine and old.practitioner != mine:
        frappe.throw("This consultation belongs to another doctor.")

# Check if form data with updated symptoms/diagnosis/drugs was submitted
has_form_data = "symptoms" in f or "diagnosis" in f or "drugs" in f
complete = f.get("complete") == "1" or f.get("complete") is True

symptoms = json.loads(f.get("symptoms") or "[]") if has_form_data else [x.complaint for x in old.symptoms]
diagnoses = json.loads(f.get("diagnosis") or "[]") if has_form_data else [x.diagnosis for x in old.diagnosis]
drugs = json.loads(f.get("drugs") or "[]") if has_form_data else None
labs = json.loads(f.get("labs") or "[]") if has_form_data else [x.lab_test_code for x in old.lab_test_prescription]

for c in symptoms:
    if not frappe.db.exists("Complaint", c):
        frappe.get_doc({"doctype": "Complaint", "complaints": c}).insert(ignore_permissions=True)
for d in diagnoses:
    if not frappe.db.exists("Diagnosis", d):
        frappe.get_doc({"doctype": "Diagnosis", "diagnosis": d}).insert(ignore_permissions=True)

# Marley creates a Medication Request for each medicine when an encounter is completed.
# They block the cancel, so cancel them first (completing the amended copy creates fresh ones).
reqs = []
link_fields = ["order_group", "patient_encounter", "encounter", "reference_dn"]
try:
    for df in frappe.get_meta("Medication Request").fields:
        if df.fieldtype == "Link" and df.options == "Patient Encounter" and df.fieldname not in link_fields:
            link_fields.append(df.fieldname)
except:
    pass

for fld in link_fields:
    try:
        for x in frappe.get_all("Medication Request", filters={fld: old.name}, fields=["name", "docstatus"]):
            seen = False
            for y in reqs:
                if y.name == x.name:
                    seen = True
            if not seen:
                reqs.append(x)
    except:
        pass
for x in reqs:
    mr = frappe.get_doc("Medication Request", x.name)
    mr.flags.ignore_permissions = True
    try:
        if mr.docstatus == 1:
            mr.cancel()
        elif mr.docstatus == 0:
            frappe.delete_doc("Medication Request", mr.name, ignore_permissions=True)
    except Exception as e:
        frappe.throw("Could not cancel Medication Request " + mr.name + ": " + str(e))

old.flags.ignore_permissions = True
try:
    old.cancel()
except Exception as e:
    frappe.throw("Could not cancel the completed consultation: " + str(e))

new = frappe.new_doc("Patient Encounter")
new.patient = old.patient
new.practitioner = old.practitioner
new.appointment = old.appointment
new.company = old.company
new.encounter_comment = (f.get("comment") if has_form_data else old.encounter_comment) or ""
if old.encounter_date:
    new.encounter_date = old.encounter_date
else:
    new.encounter_date = frappe.utils.today()
if old.get("encounter_time"):
    new.encounter_time = old.encounter_time
else:
    new.encounter_time = frappe.utils.nowtime()

if old.get("appointment_type"):
    new.appointment_type = old.appointment_type
else:
    appt_type = None
    if old.appointment:
        appt_type = frappe.db.get_value("Patient Appointment", old.appointment, "appointment_type")
    if not appt_type and frappe.db.exists("DocType", "Appointment Type"):
        appt_type = frappe.db.get_value("Appointment Type", {}, "name")
    if appt_type:
        new.appointment_type = appt_type
new.amended_from = old.name

new.set("symptoms", [])
for c in symptoms:
    new.append("symptoms", {"complaint": c})
new.set("diagnosis", [])
for d in diagnoses:
    new.append("diagnosis", {"diagnosis": d})

new.set("drug_prescription", [])
if drugs is not None:
    for dr in drugs:
        nm = (dr.get("drug") or "").strip()
        if not nm:
            continue

        form = (dr.get("form") or "").strip()
        strength = dr.get("strength")
        unit = (dr.get("unit") or "").strip()
        cls = (dr.get("mclass") or "").strip()

        # 1. Resolve or create Item (medicine name saved as both item_code and item_name)
        item_code = None
        if frappe.db.exists("Item", nm):
            item_code = nm
        else:
            try:
                item_code = frappe.db.get_value("Item", {"item_name": nm}, "name")
            except:
                pass
        if not item_code:
            try:
                item_code = frappe.db.get_value("Item", {"item_code": nm}, "name")
            except:
                pass

        meta_med = frappe.get_meta("Medication") if frappe.db.exists("DocType", "Medication") else None
        has_med_name = meta_med.has_field("medication_name") if meta_med else False
        has_item_fld = meta_med.has_field("item") if meta_med else False
        has_item_code_fld = meta_med.has_field("item_code") if meta_med else False
        has_generic_fld = meta_med.has_field("generic_name") if meta_med else False

        if not item_code and meta_med:
            if frappe.db.exists("Medication", nm):
                if has_item_fld:
                    item_code = frappe.db.get_value("Medication", nm, "item")
                elif has_item_code_fld:
                    item_code = frappe.db.get_value("Medication", nm, "item_code")

        if not item_code:
            grp = "Drug"
            if not frappe.db.exists("Item Group", "Drug"):
                grp = frappe.db.get_value("Item Group", {"is_group": 0}, "name") or "All Item Groups"

            stock_uom = "Nos"
            if unit:
                if not frappe.db.exists("UOM", unit):
                    try:
                        frappe.get_doc({"doctype": "UOM", "uom_name": unit}).insert(ignore_permissions=True)
                    except:
                        pass
                if frappe.db.exists("UOM", unit):
                    stock_uom = unit
            if not frappe.db.exists("UOM", stock_uom):
                try:
                    frappe.get_doc({"doctype": "UOM", "uom_name": stock_uom}).insert(ignore_permissions=True)
                except:
                    pass

            try:
                it = frappe.new_doc("Item")
                it.item_code = nm
                it.item_name = nm
                it.item_group = grp
                it.stock_uom = stock_uom
                it.is_stock_item = 1
                it.has_batch_no = 1
                it.has_expiry_date = 1
                it.create_new_batch = 0
                it.flags.ignore_mandatory = True
                it.insert(ignore_permissions=True, ignore_mandatory=True)
                item_code = it.name or nm
            except Exception:
                item_code = frappe.db.exists("Item", nm) or nm

        # 2. Resolve or create Medication
        med = None
        if meta_med:
            if frappe.db.exists("Medication", nm):
                med = nm
            if not med:
                for pfx in ["Tablet ", "tablet "]:
                    for sfx in [" mg", ""]:
                        old_cand = pfx + nm + sfx
                        if frappe.db.exists("Medication", old_cand):
                            try:
                                frappe.rename_doc("Medication", old_cand, nm, ignore_permissions=True)
                                med = nm
                                break
                            except Exception:
                                med = old_cand
                                break
                    if med:
                        break

            if not med and item_code:
                if has_item_fld:
                    med = frappe.db.get_value("Medication", {"item": item_code}, "name")
                elif has_item_code_fld:
                    med = frappe.db.get_value("Medication", {"item_code": item_code}, "name")
            if not med and has_generic_fld:
                med = frappe.db.get_value("Medication", {"generic_name": nm}, "name")
            if not med and has_med_name:
                med = frappe.db.get_value("Medication", {"medication_name": nm}, "name")
            if not med and item_code and frappe.db.exists("DocType", "Medication Linked Item"):
                try:
                    med = frappe.db.get_value("Medication Linked Item", {"item": item_code}, "parent")
                except:
                    pass

            if not med:
                if not cls:
                    first_cls = frappe.get_all("Medication Class", fields=["name"], limit=1)
                    if first_cls:
                        cls = first_cls[0].name
                    elif frappe.db.exists("DocType", "Medication Class"):
                        try:
                            frappe.get_doc({"doctype": "Medication Class", "medication_class": "General"}).insert(ignore_permissions=True)
                            cls = "General"
                        except:
                            pass

                st_val = 1.0
                if strength:
                    try:
                        st_val = float(strength)
                    except:
                        st_val = 1.0

                uom_val = unit or "Nos"
                if not frappe.db.exists("UOM", uom_val):
                    try:
                        frappe.get_doc({"doctype": "UOM", "uom_name": uom_val}).insert(ignore_permissions=True)
                    except:
                        pass

                try:
                    m = frappe.new_doc("Medication")
                    m.name = nm
                    m.flags.name_set = True
                    if has_med_name:
                        m.medication_name = nm
                    if has_generic_fld:
                        m.generic_name = nm
                    if has_item_fld:
                        m.item = item_code
                    if has_item_code_fld:
                        m.item_code = item_code
                    if form and meta_med.has_field("dosage_form"):
                        m.dosage_form = form
                    if cls and meta_med.has_field("medication_class"):
                        m.medication_class = cls
                    if meta_med.has_field("strength"):
                        m.strength = st_val
                    if meta_med.has_field("strength_uom"):
                        m.strength_uom = uom_val
                    m.flags.ignore_mandatory = True
                    m.insert(ignore_permissions=True, ignore_mandatory=True)
                    med = m.name or nm
                except Exception:
                    med = None

        # 3. Dosage form
        if not form and med:
            try:
                form = frappe.db.get_value("Medication", med, "dosage_form") or ""
            except:
                pass
        if not form:
            first_form = frappe.get_all("Dosage Form", fields=["name"], limit=1)
            if first_form:
                form = first_form[0].name
            else:
                form = "Tablet"

        # 4. Target field linking for Drug Prescription.drug_code
        target_dt = "Item"
        try:
            df = frappe.get_meta("Drug Prescription").get_field("drug_code")
            if df and df.options:
                target_dt = df.options
        except:
            target_dt = "Item"

        final_code = item_code
        if target_dt == "Medication" and med and frappe.db.exists("Medication", med):
            final_code = med
        elif target_dt == "Item" and item_code and frappe.db.exists("Item", item_code):
            final_code = item_code
        elif frappe.db.exists(target_dt, item_code):
            final_code = item_code
        elif med and frappe.db.exists(target_dt, med):
            final_code = med
        else:
            final_code = item_code or med

        row = {
            "drug_code": final_code,
            "dosage_form": form,
            "comment": dr.get("comment") or ""
        }
        if dr.get("dosage"):
            row["dosage"] = dr.get("dosage")
        if dr.get("period"):
            row["period"] = dr.get("period")
        new.append("drug_prescription", row)
else:
    for x in old.drug_prescription:
        row = {"drug_code": x.drug_code, "dosage_form": x.dosage_form, "comment": x.comment or ""}
        if x.dosage:
            row["dosage"] = x.dosage
        if x.period:
            row["period"] = x.period
        new.append("drug_prescription", row)

new.set("lab_test_prescription", [])
for lt in labs:
    new.append("lab_test_prescription", {"lab_test_code": lt})

new.insert(ignore_permissions=True)
if complete:
    new.submit()

frappe.response["message"] = {"encounter": new.name, "appointment": new.appointment, "completed": complete}

# Server Script: enc_load
# type: API
# doctype: -
# event: Before Insert
# api_method: enc_load
# allow_guest: 0
# frequency: All
# disabled: 0

user = frappe.session.user
is_admin = False
for r in ["Healthcare Administrator", "System Manager"]:
    if frappe.db.exists("Has Role", {"parent": user, "role": r}):
        is_admin = True
ok = is_admin
for r in ["Physician", "Nursing User"]:
    if frappe.db.exists("Has Role", {"parent": user, "role": r}):
        ok = True
if not ok:
    frappe.throw("You don't have access to consultations.")

def names(dt, limit=500):
    out = []
    try:
        if limit:
            records = frappe.get_all(dt, fields=["name"], order_by="name", limit=limit)
        else:
            records = frappe.get_all(dt, fields=["name"], order_by="name")
        for r in records:
            out.append(r.name)
    except:
        pass
    return out

appt_id = frappe.form_dict.get("appointment")
patient_id = frappe.form_dict.get("patient")
enc_id = (frappe.form_dict.get("encounter") or "").strip()

if enc_id and frappe.db.exists("Patient Encounter", enc_id):
    curr_enc = frappe.get_doc("Patient Encounter", enc_id)
    if not patient_id:
        patient_id = curr_enc.patient
    if not appt_id and curr_enc.appointment:
        appt_id = curr_enc.appointment
appt = None
if appt_id:
    appt = frappe.get_doc("Patient Appointment", appt_id)
    patient_id = appt.patient
    if not is_admin:
        mine = frappe.db.get_value("Healthcare Practitioner", {"user_id": user}, "name")
        if mine and appt.practitioner != mine:
            frappe.throw("This appointment belongs to another doctor.")
if not patient_id:
    frappe.throw("No patient selected. Open this page from the doctor desk.")

pat = frappe.get_doc("Patient", patient_id)
age = None
if pat.dob:
    d = frappe.utils.getdate(pat.dob)
    t = frappe.utils.getdate(frappe.utils.today())
    age = t.year - d.year - (1 if (t.month, t.day) < (d.month, d.day) else 0)

enc = None
vit = None
if enc_id and frappe.db.exists("Patient Encounter", enc_id):
    e = frappe.get_doc("Patient Encounter", enc_id)
    enc = {
        "name": e.name,
        "docstatus": e.docstatus,
        "amended_from": e.amended_from or "",
        "comment": e.encounter_comment or "",
        "symptoms": [x.complaint for x in e.symptoms],
        "diagnosis": [x.diagnosis for x in e.diagnosis],
        "drugs": [{"drug": x.drug_code, "form": x.dosage_form or "", "dosage": x.dosage or "",
                   "period": x.period or "", "comment": x.comment or ""} for x in e.drug_prescription],
        "labs": [x.lab_test_code for x in e.lab_test_prescription],
    }
elif appt_id:
    found = frappe.get_all("Patient Encounter",
        filters={"appointment": appt_id, "docstatus": ["<", 2]}, fields=["name"], limit=1)
    if found:
        e = frappe.get_doc("Patient Encounter", found[0].name)
        enc = {
            "name": e.name,
            "docstatus": e.docstatus,
            "amended_from": e.amended_from or "",
            "comment": e.encounter_comment or "",
            "symptoms": [x.complaint for x in e.symptoms],
            "diagnosis": [x.diagnosis for x in e.diagnosis],
            "drugs": [{"drug": x.drug_code, "form": x.dosage_form or "", "dosage": x.dosage or "",
                       "period": x.period or "", "comment": x.comment or ""} for x in e.drug_prescription],
            "labs": [x.lab_test_code for x in e.lab_test_prescription],
        }
    v = frappe.get_all("Vital Signs", filters={"appointment": appt_id, "docstatus": ["<", 2]},
        fields=["name", "docstatus", "temperature", "pulse", "respiratory_rate",
                "bp_systolic", "bp_diastolic", "height", "weight"], limit=1)
    if v:
        vit = v[0]

current_enc_name = enc.get("name") if enc else ""
current_appt_name = appt_id or ""

history = []
hx_filters = {"patient": patient_id, "docstatus": 1}
if current_enc_name:
    hx_filters["name"] = ["!=", current_enc_name]
elif current_appt_name:
    hx_filters["appointment"] = ["!=", current_appt_name]

for h in frappe.get_all("Patient Encounter", filters=hx_filters,
        fields=["name", "appointment", "encounter_date", "encounter_comment"],
        order_by="encounter_date desc", limit=5):
    if current_enc_name and h.name == current_enc_name:
        continue
    if current_appt_name and h.appointment == current_appt_name:
        continue
    hd = frappe.get_doc("Patient Encounter", h.name)
    history.append({
        "encounter": h.name,
        "name": h.name,
        "date": str(h.encounter_date),
        "appointment": h.appointment or "",
        "diagnosis": [x.diagnosis for x in hd.diagnosis],
        "comment": h.encounter_comment or "",
    })

# Auto-cleanup: rename any Medications that were prefixed with "Tablet "
if frappe.db.exists("DocType", "Medication"):
    try:
        bad_meds = frappe.get_all("Medication", filters=[["name", "like", "Tablet %"]], fields=["name"], limit=50)
        for bm in bad_meds:
            clean_name = bm.name
            if clean_name.startswith("Tablet "):
                clean_name = clean_name[7:]
            elif clean_name.startswith("tablet "):
                clean_name = clean_name[7:]
            if clean_name.endswith(" mg"):
                clean_name = clean_name[:-3]
            clean_name = clean_name.strip()
            if clean_name and clean_name != bm.name and not frappe.db.exists("Medication", clean_name):
                try:
                    frappe.rename_doc("Medication", bm.name, clean_name, ignore_permissions=True)
                except Exception:
                    pass
    except Exception:
        pass

# Pharmacy stock items that are not Medications yet (including ones with no batches or no stock).
# Choosing one in the consultation creates the Medication and links it to that item.
stock_items = []
try:
    meds = names("Medication")
    linked = []
    try:
        for r in frappe.get_all("Medication", fields=["item"], limit=500):
            if r.get("item"):
                linked.append(r.get("item"))
    except:
        pass
    try:
        for r in frappe.get_all("Medication Linked Item", fields=["item"], limit=2000):
            if r.get("item"):
                linked.append(r.get("item"))
    except:
        pass
    cands = frappe.get_all("Item", filters={"disabled": 0, "is_stock_item": 1, "item_group": "Drug"},
        fields=["name", "item_name"], order_by="item_name", limit=500)
    if len(cands) < 500:
        for x in frappe.get_all("Item", filters={"disabled": 0, "is_stock_item": 1, "has_batch_no": 1},
                fields=["name", "item_name"], order_by="item_name", limit=500):
            dup = False
            for y in cands:
                if y.name == x.name:
                    dup = True
            if not dup:
                cands.append(x)
    for x in cands:
        nm = x.item_name or x.name
        if x.name in linked or nm in meds or x.name in meds or nm in stock_items:
            continue
        stock_items.append(nm)
except:
    pass

igs = []
try:
    for r in frappe.get_all("Item Group", filters={"is_group": 0}, fields=["name"], order_by="name", limit=200):
        igs.append(r.name)
except:
    pass

med_forms = {}
try:
    for m in frappe.get_all("Medication", fields=["name", "dosage_form"], limit=500):
        if m.dosage_form:
            med_forms[m.name] = m.dosage_form
except:
    pass

token = ""
try:
    token = frappe.session.get("csrf_token") or ""
except:
    token = ""

appt_out = None
if appt:
    appt_out = {"id": appt.name, "date": str(appt.appointment_date),
                "time": str(appt.appointment_time), "type": appt.appointment_type}

frappe.response["message"] = {
    "patient": {"id": pat.name, "name": pat.patient_name, "age": age,
                "sex": pat.sex or "", "mobile": pat.mobile or ""},
    "appointment": appt_out,
    "practitioner": appt.practitioner if appt else "",
    "encounter": enc,
    "vitals": vit,
    "history": history,
    "lists": {
        "complaints": names("Complaint"),
        "diagnoses": names("Diagnosis"),
        "medications": names("Medication"),
        "items": stock_items,
        "item_groups": igs,
        "dosages": names("Prescription Dosage"),
        "periods": names("Prescription Duration"),
        "labs": names("Lab Test Template"),
        "forms": names("Dosage Form"),
        "classes": names("Medication Class", limit=None),
        "uoms": names("UOM"),
    },
    "med_forms": med_forms,
    "csrf": token,
}

# Server Script: enc_save
# type: API
# doctype: -
# event: Before Insert
# api_method: enc_save
# allow_guest: 0
# frequency: All
# disabled: 0

user = frappe.session.user
ok = False
for r in ["Physician", "Healthcare Administrator", "System Manager"]:
    if frappe.db.exists("Has Role", {"parent": user, "role": r}):
        ok = True
if not ok:
    frappe.throw("Only doctors can save a consultation.")

f = frappe.form_dict
appt_id = f.get("appointment")
patient = f.get("patient")
prac = f.get("practitioner")
complete = f.get("complete") == "1" or f.get("complete") is True
if not patient or not prac:
    frappe.throw("Open this page from the doctor desk so the patient and doctor are known.")

company = frappe.db.get_single_value("Global Defaults", "default_company")
symptoms = json.loads(f.get("symptoms") or "[]")
diagnoses = json.loads(f.get("diagnosis") or "[]")
drugs = json.loads(f.get("drugs") or "[]")
labs = json.loads(f.get("labs") or "[]")
vitals = json.loads(f.get("vitals") or "{}")

for c in symptoms:
    if not frappe.db.exists("Complaint", c):
        frappe.get_doc({"doctype": "Complaint", "complaints": c}).insert(ignore_permissions=True)
for d in diagnoses:
    if not frappe.db.exists("Diagnosis", d):
        frappe.get_doc({"doctype": "Diagnosis", "diagnosis": d}).insert(ignore_permissions=True)

# Vital signs (optional)
vs = None
has_vitals = False
for k in vitals:
    if vitals.get(k):
        has_vitals = True
if has_vitals:
    old = []
    if appt_id:
        old = frappe.get_all("Vital Signs", filters={"appointment": appt_id, "docstatus": 0},
            fields=["name"], limit=1)
    if old:
